14. use crate::{
15.     hal::mem::FrameAddress,
16.     mm::phys::{
17.         frame,
18.         kframe::KernelFrame,
19.         upool::{
20.             Upool,
21.             UserFrame,
22.         },
23.     },
24. };
25. use ::alloc::vec::Vec;
26. use ::arch::mem;
27. use ::core::{
28.     hint::unlikely,
29.     mem::MaybeUninit,
30.     sync::atomic::{
31.         AtomicBool,
32.         Ordering,
33.     },
34. };
35. use ::sys::error::{
36.     Error,
37.     ErrorCode,
38. };
39. use ::vstd::prelude::*;
40. 
41. //==================================================================================================
42. // Constants
43. //==================================================================================================
44. 
45. // Use relaxed ordering for all atomic operations to mitigate synchronization overhead. It is safe
46. // to use this ordering semantics because Nanvix is a single-core system, and the kernel runs with
47. // interrupts disabled.
48. const ORDER: Ordering = Ordering::Relaxed;
49. 
50. //==================================================================================================
51. // Global Variables
52. //==================================================================================================
53. 
54. /// Physical memory manager storage.
55. static mut PHYS_MEMORY_MANAGER: MaybeUninit<PhysMemoryManager> = MaybeUninit::uninit();
56. 
57. /// Whether the physical memory manager has been initialized.
58. static PHYS_MEMORY_MANAGER_INIT: AtomicBool = AtomicBool::new(false);
59. 
60. //==================================================================================================
61. // Structures
62. //==================================================================================================
63. 
64. ///
65. /// # Description
66. ///
67. /// Physical memory manager.
68. ///
69. pub struct PhysMemoryManager {
70.     upool: Upool,
71. }
72. 
73. //==================================================================================================
74. // Implementations
75. //==================================================================================================
76. 
77. impl PhysMemoryManager {
78.     ///
79.     /// # Description
80.     ///
81.     /// Initializes the physical memory manager singleton.
82.     ///
83.     /// # Parameters
84.     ///
85.     /// - `upool`: User page pool.
86.     ///
87.     /// # Errors
88.     ///
89.     /// Returns `InvalidArgument` if the singleton has already been initialized.
90.     ///
91.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
92.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
93.             return Err(Error::new(
94.                 ErrorCode::InvalidArgument,
95.                 "physical memory manager already initialized",
96.             ));
97.         }
98. 
99.         // SAFETY: this happens during kernel initialization and no other threads are running.
100.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
101.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
102.         Ok(())
103.     }
104. 
105.     ///
106.     /// # Description
107.     ///
108.     /// Gets a mutable reference to the physical memory manager.
109.     ///
110.     /// # Panics
111.     ///
112.     /// Panics if the physical memory manager is not initialized.
113.     ///
114.     /// # Safety
115.     ///
116.     /// This function is unsafe because it returns a mutable reference to a global variable.
117.     ///
118.     /// The caller must ensure:
119.     ///
120.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
121.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
122.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
123.     ///   re-entrant or concurrent call can alias the reference.
124.     ///
125.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
126.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
127.             panic!("physical memory manager is not initialized");
128.         }
129. 
130.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
131.         PHYS_MEMORY_MANAGER.assume_init_mut()
132.     }
133. 
134.     ///
135.     /// # Description
136.     ///
137.     /// Allocates user frames into caller-provided storage.
138.     ///
139.     /// The returned frames are not guaranteed to be physically contiguous.
140.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
141.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
142.     ///
143.     /// # Parameters
144.     ///
145.     /// - `count`: Number of frames to allocate.
146.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
147.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
148.     ///
149.     /// # Return Values
150.     ///
151.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
152.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
153.     /// back to empty.
154.     ///
155.     pub fn alloc_many_user_frames(
156.         &mut self,
157.         count: usize,
158.         frames: &mut Vec<UserFrame>,
159.     ) -> Result<(), Error> {
160.         if !frames.is_empty() {
161.             let reason: &str = "frames vector is not empty";
162.             error!("{reason}");
163.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
164.         }
165.         if frames.capacity() < count {
166.             let reason: &str = "frames vector has insufficient capacity";
167.             error!("{reason}");
168.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
169.         }
170. 
171.         // A zero-sized allocation is trivially satisfied.
172.         if count == 0 {
173.             return Ok(());
174.         }
175. 
176.         Self::check_user_watermark(count)?;
177. 
178.         for _ in 0..count {
179.             match self.upool.alloc() {
180.                 Ok(frame) => frames.push(frame),
181.                 Err(error) => {
182.                     frames.clear();
183.                     return Err(error);
184.                 },
185.             }
186.         }
187.         Ok(())
188.     }
189. 
190.     ///
191.     /// # Description
192.     ///
193.     /// Allocates a single user frame, applying the same kernel watermark check as
194.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
195.     /// hot paths such as copy-on-write fault resolution, where allocating an
196.     /// intermediate [`Vec`] would be wasteful.
197.     ///
198.     /// # Returns
199.     ///
200.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
201.     /// instead.
202.     ///
203.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
204.         Self::check_user_watermark(1)?;
205.         self.upool.alloc()
206.     }
207. 
208.     ///
209.     /// # Description
210.     ///
211.     /// Rejects user allocations of `count` frames that would breach the kernel
212.     /// watermark, i.e. that would drop the number of free frames below
213.     /// [`config::kernel::KERNEL_WATERMARK`].
214.     ///
215.     /// # Parameters
216.     ///
217.     /// - `count`: Number of user frames the caller intends to allocate.
218.     ///
219.     /// # Returns
220.     ///
221.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
222.     ///
223.     fn check_user_watermark(count: usize) -> Result<(), Error> {
224.         let watermark_threshold: usize = config::kernel::KERNEL_WATERMARK
225.             .checked_add(count)
226.             .ok_or_else(|| {
227.                 let reason: &str = "watermark + count overflow";
228.                 error!("{reason}");
229.                 Error::new(ErrorCode::InvalidArgument, reason)
230.             })?;
231.         if frame::free_count() < watermark_threshold {
232.             let reason: &str = "would breach kernel watermark";
233.             error!("{reason}");
234.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
235.         }
236.         Ok(())
237.     }
238. 
239.     ///
240.     /// # Description
241.     ///
242.     /// Allocates a kernel frame.
243.     ///
244.     /// Kernel allocations bypass the watermark — no artificial ceiling.
245.     ///
246.     /// # Return Values
247.     ///
248.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
249.     ///
250.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
251.         let frame_addr: FrameAddress = frame::alloc()?;
252.         KernelFrame::new(frame_addr).inspect_err(|e| {
253.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
254.             if let Err(free_err) = frame::free(frame_addr) {
255.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
256.             }
257.         })
258.     }
259. 
260.     ///
261.     /// # Description
262.     ///
263.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
264.     ///
265.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
266.     /// mapping and the hardware stack pointer traverses the region linearly.
267.     /// Kernel allocations bypass the watermark — no artificial ceiling.
268.     ///
269.     /// # Parameters
270.     ///
271.     /// - `count`: Number of frames to allocate.
272.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
273.     ///   those frames' addresses.
274.     ///
275.     /// # Return Values
276.     ///
277.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
278.     /// contiguous entries. Upon failure, an error is returned instead.
279.     ///
280.     pub fn alloc_many_kernel_frames(
281.         &mut self,
282.         count: usize,
283.         frames: &mut Vec<KernelFrame>,
284.     ) -> Result<(), Error> {
285.         // Check if caller-provided vector is not empty.
286.         if !frames.is_empty() {
287.             let reason: &str = "frames vector is not empty";
288.             error!("{reason}");
289.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
290.         }
291.         if frames.capacity() < count {
292.             let reason: &str = "frames vector has insufficient capacity";
293.             error!("{reason}");
294.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
295.         }
296. 
297.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
298.         let base_raw: usize = base_addr.into_raw_value();
299.         for i in 0..count {
300.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
301.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
302.                 Ok(kf) => frames.push(kf),
303.                 Err(e) => {
304.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
305.                     frames.clear();
306.                     // Free remaining un-wrapped frames from the contiguous allocation.
307.                     for j in i..count {
308.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
309.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
310.                             if let Err(e) = frame::free(fa) {
311.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
312.                             }
313.                         }
314.                     }
315.                     return Err(e);
316.                 },
317.             }
318.         }
319.         Ok(())
320.     }
321. }
322.

