3. 
4. // PhysMemoryManager - Proofs
5. //
6. // Proven lemmas that map the caller expectations recorded in
7. // `verus-ai-logs/nanvix-phys-phys-mod/caller_analysis.md` onto the `PhysMemView`
8. // transition vocabulary defined in `mod.spec.rs`. These discharge the abstract
9. // frame-reservation semantics that the exec-level `#[verus_spec]` contracts in
10. // `mod.rs` / `frame.rs` summarize.
11. 
12. verus! {
13. 
14. /// `init` *establishes* (not merely preserves) the allocator invariant.
15. ///
16. /// Caller expectation: "after `Ok`, `instance().inv()` (i.e. `FrameAllocView::wf`)
17. /// holds for all later `mm::phys` operations." Booting from a well-formed initial
18. /// bitmap state yields an initialized, well-formed `PhysMemView`.
19. pub proof fn lemma_spec_initialize_establishes_inv(pre: PhysMemView, initial: FrameAllocView)
20.     requires
21.         initial.wf(),
22.     ensures
23.         pre.spec_initialize(initial).initialized,
24.         pre.spec_initialize(initial).inv(),
25.         pre.spec_initialize(initial).frames == initial,
26. {
27. }
28. 
29. /// Booking a set of currently-free, page-aligned frames at once preserves the
30. /// subsystem invariant and reserves all of them.
31. ///
32. /// Generalizes `Inner::alloc_range`'s `Ok` post-state from a contiguous region to
33. /// an arbitrary frame set: every frame in `frames` ends up allocated and out of
34. /// `free_frames`, and the `FrameAllocView` well-formedness is maintained.
35. pub proof fn lemma_spec_book_frames_preserves_inv(pre: PhysMemView, frames: Set<int>)
36.     requires
37.         pre.inv(),
38.         pre.initialized,
39.         frames.subset_of(pre.frames.free_frames),
40.         forall|a: int| frames.contains(a) ==> a % spec_page_size() == 0,
41.     ensures
42.         pre.spec_book_frames(frames).inv(),
43.         pre.spec_book_frames(frames).initialized,
44.         forall|a: int| frames.contains(a)
45.             ==> #[trigger] pre.spec_book_frames(frames).frames.allocated_frames.contains(a),
46.         forall|a: int| frames.contains(a)
47.             ==> #[trigger] pre.spec_book_frames(frames).frames.free_frames.contains(a) == false,
48. {
49.     let pre_f = pre.frames;
50.     let post = pre.spec_book_frames(frames);
51.     let post_f = post.frames;
52. 
53.     assert(pre_f.wf());
54. 
55.     // Key fact: the refcount domain is exactly the allocated set (pre-state).
56.     assert forall|x: int| #[trigger] pre_f.refcounts.contains_key(x) implies pre_f.allocated_frames.contains(x) by {
57.         assert(pre_f.refcounts[x] > 0);
58.     }
59. 
60.     // Reservation post-state membership.
61.     assert forall|a: int| frames.contains(a)
62.         implies #[trigger] post_f.allocated_frames.contains(a) by {
63.     }
64.     assert forall|a: int| #[trigger] frames.contains(a)
65.         implies post_f.free_frames.contains(a) == false by {
66.     }
67. 
68.     assert(post_f.wf()) by {
69.         // (1) allocated frames are page-aligned.
70.         assert forall|x: int| post_f.allocated_frames.contains(x)
71.             implies x % spec_page_size() == 0 by {
72.             if pre_f.allocated_frames.contains(x) {
73.             } else {
74.                 assert(frames.contains(x));
75.             }
76.         }
77.         // (2) free frames are page-aligned.
78.         assert forall|x: int| post_f.free_frames.contains(x)
79.             implies x % spec_page_size() == 0 by {
80.             assert(pre_f.free_frames.contains(x));
81.         }
82.         // (3) allocated and free are disjoint.
83.         assert forall|x: int| post_f.allocated_frames.contains(x)
84.             implies !post_f.free_frames.contains(x) by {
85.             if pre_f.allocated_frames.contains(x) {
86.                 assert(!pre_f.free_frames.contains(x));
87.             }
88.         }
89.         // (4) allocated iff positive refcount.
90.         assert forall|x: int| #[trigger] post_f.allocated_frames.contains(x)
91.             <==> (post_f.refcounts.contains_key(x) && post_f.refcounts[x] > 0) by {
92.             if frames.contains(x) {
93.                 assert(post_f.refcounts[x] == 1);
94.             } else if pre_f.allocated_frames.contains(x) {
95.                 assert(pre_f.refcounts.contains_key(x));
96.                 assert(pre_f.refcounts[x] > 0);
97.                 assert(post_f.refcounts[x] == pre_f.refcounts[x]);
98.             }
99.         }
100.         // (5) free frames have no refcount entry.
101.         assert forall|x: int| #[trigger] post_f.free_frames.contains(x)
102.             implies !post_f.refcounts.contains_key(x) by {
103.             assert(pre_f.free_frames.contains(x));
104.             assert(!pre_f.allocated_frames.contains(x));
105.             assert(!pre_f.refcounts.contains_key(x));
106.             assert(!frames.contains(x));
107.         }
108.         // (6) refcounts are within the u8 range.
109.         assert forall|x: int| post_f.refcounts.contains_key(x)
110.             implies 0 < post_f.refcounts[x] <= 255 by {
111.             if frames.contains(x) {
112.                 assert(post_f.refcounts[x] == 1);
113.             } else {
114.                 assert(pre_f.refcounts.contains_key(x));
115.             }
116.         }
117.     }
118. }
119. 
120. /// Booking one covered, currently-free frame preserves the subsystem invariant
121. /// and reserves exactly that frame.
122. ///
123. /// Mirrors `Inner::book`'s `Ok` post-state: `addr` moves from `free_frames` to
124. /// `allocated_frames` with `refcounts[addr] == 1`. Proven as the singleton case of
125. /// `lemma_spec_book_frames_preserves_inv`.
126. pub proof fn lemma_spec_book_frame_preserves_inv(pre: PhysMemView, addr: int)
127.     requires
128.         pre.inv(),
129.         pre.initialized,
130.         pre.frames.free_frames.contains(addr),
131.     ensures
132.         pre.spec_book_frame(addr).inv(),
133.         pre.spec_book_frame(addr).initialized,
134.         pre.spec_book_frame(addr).frames.allocated_frames.contains(addr),
135.         !pre.spec_book_frame(addr).frames.free_frames.contains(addr),
136.         pre.spec_book_frame(addr).frames.refcounts[addr] == 1,
137. {
138.     assert(pre.frames.wf());
139.     // `addr` is page-aligned because it is a free frame in a well-formed view.
140.     assert(addr % spec_page_size() == 0);
141. 
142.     let single = Set::<int>::empty().insert(addr);
143.     assert(single.subset_of(pre.frames.free_frames));
144.     assert forall|a: int| single.contains(a) implies a % spec_page_size() == 0 by {
145.         assert(a == addr);
146.     }
147.     lemma_spec_book_frames_preserves_inv(pre, single);
148. 
