 /// A type that represents a kernel frame.
 #[derive(Debug)]
 pub struct KernelFrame {
     /// Frame address.
     base: FrameAddress,
 }

 impl KernelFrame {
     ///
     /// # Description
     ///
     /// Instantiates a kernel frame.
     ///
     /// # Parameters
